files.utils.R:
trim_left = function(x) {
  sub("^[[:space:]]+", "", x)
}
trim_both = function(x) {
  x = sub("^[[:space:]]+", "", x)
  sub("[[:space:]]+$", "", x)
}
clean_names = function(df) {
  names(df) = tolower(trim_both(names(df)))
  df
}
clean_labels = function(x) {
  toupper(trim_left(x))
}

